import os,glob,re

def load():
    d=os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        # Try to find the session file
        import glob
        dirs = glob.glob(os.path.join('/home/ubuntu/runs/paper/qwen-hpl0-u1-turns/play/users/u000/system/state/sessions', '*'))
        for dd in dirs[:5]:
            fname = os.path.basename(dd) + '.jsonl'
            try:
                t = open(dd + '/' + fname).read()
                if 'Demo' in t or 'Test input' in t:
                    d = dd
                    break
            except:
                continue
    if not d:
        print("No session found")
        return
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

